#!/usr/bin/env python3
# ---------------------------------------------------------------------------
# This file was generated by Claude (Anthropic), in a conversation building
# this benchmark-tracking tool. It's yours now -- edit it freely; nothing
# regenerates it automatically.
# ---------------------------------------------------------------------------
"""
loxbench: run a Lox interpreter against the benchmark suite and track its
results over time.

Usage:
    python run.py run <executable> [--benchmarks DIR] [--label TEXT]
                                    [--timeout SECONDS] [--history FILE] [--no-open]
    python run.py list [--history FILE]
    python run.py report [--all] [--history FILE]
    python run.py history <benchmark.lox> [--history FILE]
    python run.py plot [--output FILE] [--history FILE] [--no-open]
    python run.py show <run_id> [--history FILE]

`run` does everything in one step: it finds the benchmark scripts (in
benchmark/tests-lite-rox, next to where you run this from), executes the
given interpreter against each one, parses every number it prints, and
appends a new row to history.json -- along with the interpreter's path and
its (shortened) git commit SHA. Nothing is overwritten; every `run` adds a
new record. It then regenerates the HTML chart report and opens it in
Firefox automatically (pass --no-open to skip that).

Example:
    python run.py run mothership/clox --label "official clox"
    python run.py run mothership/jlox --label "official jlox"
    python run.py run my-clox/build/clox --label "baseline"
    ... change your clox, rebuild ...
    python run.py run my-clox/build/clox --label "after inline caching"
    python run.py report
    python run.py history fib.lox
"""

import argparse
import json
import shutil
import subprocess
import sys
import uuid
from datetime import datetime, timezone
from pathlib import Path

from parser import parse_output
from plot import write_report
from semantics import is_check_entry, is_higher_better
from correctness import find_correctness_errors, build_jlox_reference, format_mismatch

DEFAULT_HISTORY_FILE = str(Path(__file__).resolve().parent / "history.json")
DEFAULT_REPORT_FILE = str(Path(__file__).resolve().parent / "benchmark_report.html")
DEFAULT_TIMEOUT = 120  # seconds, per benchmark script
BENCHMARK_DIR = Path("benchmark") / "tests-lite-rox"


# --------------------------------------------------------------------------
# History storage
# --------------------------------------------------------------------------

def load_history(path):
    p = Path(path)
    if not p.exists():
        return {"runs": []}
    with p.open("r") as f:
        return json.load(f)


def save_history(path, data):
    with Path(path).open("w") as f:
        json.dump(data, f, indent=2)
        f.write("\n")


# --------------------------------------------------------------------------
# Locating things
# --------------------------------------------------------------------------

def find_benchmark_dir(explicit_dir):
    d = Path(explicit_dir) if explicit_dir else BENCHMARK_DIR
    if not d.is_dir():
        sys.exit(f"error: benchmark directory '{d}' not found (looked relative to "
                  f"the current directory). Pass --benchmarks <dir> if it's elsewhere.")
    return d


def find_git_sha(executable_path):
    """Walk up from the executable looking for a .git directory, and return
    the short commit SHA of that repo, or None if not found / git failed."""
    d = Path(executable_path).resolve().parent
    repo_root = None
    for candidate in [d, *d.parents]:
        if (candidate / ".git").exists():
            repo_root = candidate
            break
    if repo_root is None:
        return None
    try:
        result = subprocess.run(
            ["git", "-C", str(repo_root), "rev-parse", "--short", "HEAD"],
            capture_output=True, text=True, timeout=10,
        )
        if result.returncode == 0:
            return result.stdout.strip()
    except (OSError, subprocess.SubprocessError):
        pass
    return None


def open_in_firefox(path):
    if shutil.which("firefox") is None:
        print(f"  (firefox not found on $PATH -- open {path} manually)")
        return
    try:
        subprocess.Popen(["firefox", str(path)],
                          stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except OSError as e:
        print(f"  (couldn't launch firefox: {e} -- open {path} manually)")


# --------------------------------------------------------------------------
# Running benchmarks
# --------------------------------------------------------------------------

def run_benchmarks(executable_path, benchmark_dir, timeout):
    exe = str(Path(executable_path))
    lox_files = sorted(benchmark_dir.glob("*.lox"))
    results = {}
    for lox_file in lox_files:
        name = lox_file.name
        try:
            proc = subprocess.run(
                [exe, str(lox_file)],
                capture_output=True, text=True, timeout=timeout,
            )
            combined_output = proc.stdout + proc.stderr
        except subprocess.TimeoutExpired:
            results[name] = {"entries": [], "error": f"timed out after {timeout}s"}
            continue
        except OSError as e:
            results[name] = {"entries": [], "error": f"failed to execute: {e}"}
            continue

        results[name] = parse_output(combined_output)
    return results


# --------------------------------------------------------------------------
# Commands
# --------------------------------------------------------------------------

def cmd_run(args):
    exe_path = Path(args.executable)
    if not exe_path.exists():
        sys.exit(f"error: executable '{exe_path}' does not exist")

    benchmark_dir = find_benchmark_dir(args.benchmarks)
    git_sha = find_git_sha(exe_path)
    benchmarks = run_benchmarks(exe_path.resolve(), benchmark_dir, args.timeout)

    run = {
        "id": uuid.uuid4().hex[:8],
        "timestamp": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "executable": str(exe_path.resolve()),
        "git_sha": git_sha,
        "label": args.label or "",
        "benchmark_dir": str(benchmark_dir.resolve()),
        "benchmarks": benchmarks,
    }

    history = load_history(args.history)
    history["runs"].append(run)
    save_history(args.history, history)

    ok = [n for n, b in benchmarks.items() if b["error"] is None]
    bad = [n for n, b in benchmarks.items() if b["error"] is not None]
    print(f"Recorded run {run['id']} for {run['executable']} "
          f"(git sha: {git_sha or 'unknown'}) into {args.history}")
    print(f"  benchmark dir: {benchmark_dir.resolve()}")
    if ok:
        print(f"  parsed OK:  {', '.join(sorted(ok))}")
    if bad:
        print(f"  errors:     {', '.join(sorted(bad))}")
        for n in sorted(bad):
            print(f"    - {n}: {benchmarks[n]['error']}")

    reference = build_jlox_reference(history)
    if not reference:
        print("  (no correctness check: no 'jlox' run recorded yet to use as a reference)")
    else:
        correctness_errors = find_correctness_errors(history, reference=reference, run_ids={run["id"]})
        if correctness_errors:
            print("  CORRECTNESS ERRORS (checked against the recorded jlox reference):")
            for e in correctness_errors:
                print(f"    - {e['benchmark']} '{e['label']}': {format_mismatch(e)}")

    if not args.no_open:
        report_path = args.report_output or DEFAULT_REPORT_FILE
        write_report(history, report_path)
        print(f"  Wrote {report_path} and opening it in Firefox...")
        open_in_firefox(report_path)


def cmd_list(args):
    history = load_history(args.history)
    if not history["runs"]:
        print("No runs recorded yet.")
        return
    for run in history["runs"]:
        n_ok = sum(1 for b in run["benchmarks"].values() if b["error"] is None)
        n_total = len(run["benchmarks"])
        sha = run.get("git_sha") or "n/a"
        print(f"{run['id']}  {run['timestamp']}  sha={sha:<10} "
              f"{n_ok}/{n_total} ok  {run['executable']}"
              f"{'  - ' + run['label'] if run['label'] else ''}")


def _latest_runs_per_executable(history):
    latest = {}
    for run in history["runs"]:
        latest[run["executable"]] = run  # later runs overwrite earlier
    return list(latest.values())


def _col_label(run):
    sha = run.get("git_sha") or run["id"]
    base = Path(run["executable"]).name
    return f"{base} [{sha}]"


def cmd_report(args):
    history = load_history(args.history)
    if not history["runs"]:
        print("No runs recorded yet. Use 'run' first.")
        return

    runs = history["runs"] if args.all else _latest_runs_per_executable(history)

    reference = build_jlox_reference(history)
    if not reference:
        print("(no 'jlox' run recorded yet -- correctness checks against it are skipped)")
    correctness_errors = find_correctness_errors(history, reference=reference,
                                                  run_ids={r["id"] for r in runs})
    if correctness_errors:
        print("CORRECTNESS ERRORS (value disagrees with the recorded jlox reference):")
        for e in correctness_errors:
            print(f"  [{e['run_id']}] {Path(e['executable']).name}  {e['benchmark']} "
                  f"'{e['label']}': {format_mismatch(e)}")
        print()

    bench_names = sorted({name for run in runs for name in run["benchmarks"]})
    col_headers = [_col_label(r) for r in runs]
    col_width = max([len(h) for h in col_headers] + [10]) + 2

    for bench in bench_names:
        blocks = [run["benchmarks"].get(bench) for run in runs]

        # If every run errored (or is missing) on this benchmark, say so and move on.
        if all(b is None or b["error"] is not None for b in blocks):
            print(f"=== {bench} ===")
            header = "".ljust(0) + "".join(h.ljust(col_width) for h in col_headers)
            print(header)
            row = ""
            for b in blocks:
                cell = "ERROR" if (b and b["error"]) else "n/a"
                row += cell.ljust(col_width)
            print(row)
            for run, b in zip(runs, blocks):
                if b and b["error"]:
                    print(f"  {_col_label(run)}: {b['error']}")
            print()
            continue

        max_len = max((len(b["entries"]) for b in blocks if b and not b["error"]), default=0)

        # Skip correctness-check positions (e.g. tree depth, checksums) --
        # those get validated above, not charted/tabulated as if they were
        # a performance number.
        indices = [i for i in range(max_len)
                   if not is_check_entry(bench, i, _first_label(blocks, i))]
        if not indices:
            continue  # this whole benchmark was correctness-check output

        print(f"=== {bench} ===")
        labels = []
        for i in indices:
            lbl = _first_label(blocks, i) or f"#{i}"
            if is_higher_better(bench, i):
                lbl += "  (higher is better)"
            labels.append(lbl)
        name_width = max([len(l) for l in labels] + [len("benchmark")]) + 2

        header = "".ljust(name_width) + "".join(h.ljust(col_width) for h in col_headers)
        print(header)
        for i, lbl in zip(indices, labels):
            row = lbl.ljust(name_width)
            for b in blocks:
                if b is None:
                    cell = "n/a"
                elif b["error"]:
                    cell = "ERROR"
                elif i < len(b["entries"]):
                    cell = f"{b['entries'][i]['value']:.6g}"
                else:
                    cell = "-"
                row += cell.ljust(col_width)
            print(row)
        for run, b in zip(runs, blocks):
            if b and b["error"]:
                print(f"  {_col_label(run)}: {b['error']}")
        print()

    if not args.all:
        print("(Showing the latest run per executable path. Use --all to see every historical run.)")


def _first_label(blocks, index):
    for b in blocks:
        if b and not b["error"] and index < len(b["entries"]):
            lbl = b["entries"][index]["label"]
            if lbl:
                return lbl
    return None


def cmd_history(args):
    history = load_history(args.history)
    rows = []
    for run in history["runs"]:
        block = run["benchmarks"].get(args.benchmark)
        if block is None:
            continue
        rows.append((run, block))

    if not rows:
        print(f"No recorded runs for benchmark '{args.benchmark}'.")
        return

    reference = build_jlox_reference(history)
    if not reference:
        print("(no 'jlox' run recorded yet -- correctness checks against it are skipped)")

    print(f"History for {args.benchmark}:")
    for run, block in rows:
        sha = run.get("git_sha") or "n/a"
        label_part = f"  - {run['label']}" if run["label"] else ""
        header = (f"  {run['timestamp']}  [{run['id']}] sha={sha} "
                  f"{Path(run['executable']).name}{label_part}")
        print(header)
        if block["error"]:
            print(f"      ERROR: {block['error']}")
            continue
        for i, entry in enumerate(block["entries"]):
            if is_check_entry(args.benchmark, i, entry["label"]):
                continue  # correctness-check value, not a metric -- see 'report' for validation
            lbl = entry["label"] or f"#{i}"
            if is_higher_better(args.benchmark, i):
                lbl += " (higher is better)"
            print(f"      {lbl}: {entry['value']:.6g}")


def cmd_plot(args):
    history = load_history(args.history)
    if not history["runs"]:
        print("No runs recorded yet. Use 'run' first.")
        return
    output_path = args.output or DEFAULT_REPORT_FILE
    write_report(history, output_path)
    print(f"Wrote {output_path}")
    if args.no_open:
        print("Open it in a browser to view the charts.")
    else:
        print("Opening it in Firefox...")
        open_in_firefox(output_path)


def cmd_show(args):
    history = load_history(args.history)
    run = next((r for r in history["runs"] if r["id"] == args.run_id), None)
    if run is None:
        sys.exit(f"No run with id '{args.run_id}' found.")
    print(json.dumps(run, indent=2))


# --------------------------------------------------------------------------
# CLI wiring
# --------------------------------------------------------------------------

def _add_history_arg(p, top_level=False):
    # On the top-level parser we set the real default. On subparsers we use
    # SUPPRESS as the default so that, when --history is given *before* the
    # subcommand (e.g. `run.py --history X run ...`), argparse doesn't
    # clobber that value with the subparser's own default when it finishes
    # parsing the remaining args into the same namespace.
    default = DEFAULT_HISTORY_FILE if top_level else argparse.SUPPRESS
    p.add_argument("--history", default=default,
                    help=f"Path to the history JSON file (default: {DEFAULT_HISTORY_FILE})")


def main():
    parser = argparse.ArgumentParser(description="Run and track Lox interpreter benchmark results.")
    _add_history_arg(parser, top_level=True)
    sub = parser.add_subparsers(dest="command", required=True)

    p_run = sub.add_parser("run", help="Run an interpreter against the benchmark suite and record the results")
    p_run.add_argument("executable", help="Path to the Lox interpreter executable (e.g. mothership/clox)")
    p_run.add_argument("--benchmarks", default=None,
                        help=f"Directory of .lox benchmark scripts (default: {BENCHMARK_DIR})")
    p_run.add_argument("--label", default="", help="Free-text note, e.g. 'baseline', 'after NaN-boxing'")
    p_run.add_argument("--timeout", type=float, default=DEFAULT_TIMEOUT,
                        help=f"Per-benchmark timeout in seconds (default: {DEFAULT_TIMEOUT})")
    p_run.add_argument("--no-open", action="store_true",
                        help="Don't regenerate/open the HTML report in Firefox after this run")
    p_run.add_argument("--report-output", default=None,
                        help=f"Where to write the auto-generated report (default: {DEFAULT_REPORT_FILE})")
    _add_history_arg(p_run)
    p_run.set_defaults(func=cmd_run)

    p_list = sub.add_parser("list", help="List all recorded runs")
    _add_history_arg(p_list)
    p_list.set_defaults(func=cmd_list)

    p_report = sub.add_parser("report", help="Show every recorded number, grouped by benchmark")
    p_report.add_argument("--all", action="store_true",
                           help="Show every historical run, not just the latest per executable path")
    _add_history_arg(p_report)
    p_report.set_defaults(func=cmd_report)

    p_history = sub.add_parser("history", help="Show every recorded run for one benchmark, in order")
    p_history.add_argument("benchmark", help="Benchmark file name, e.g. fib.lox")
    _add_history_arg(p_history)
    p_history.set_defaults(func=cmd_history)

    p_plot = sub.add_parser("plot", help="Generate the HTML chart report from the history and open it")
    p_plot.add_argument("--output", default=None,
                         help=f"Output HTML path (default: {DEFAULT_REPORT_FILE})")
    p_plot.add_argument("--no-open", action="store_true", help="Don't open the report in Firefox")
    _add_history_arg(p_plot)
    p_plot.set_defaults(func=cmd_plot)

    p_show = sub.add_parser("show", help="Dump the full raw record for one run id")
    p_show.add_argument("run_id")
    _add_history_arg(p_show)
    p_show.set_defaults(func=cmd_show)

    args = parser.parse_args()
    args.func(args)


if __name__ == "__main__":
    main()
